-- Requires postgres 18 for uuidv7(). Ids are generated by the application in normal use; the
-- default is there so fixtures and psql-level inserts do not have to invent one.
--
-- Enumerations are stored as text with a CHECK rather than as postgres enum types: adding a
-- variant stays a one-line migration instead of an ALTER TYPE, and no derive crate is needed
-- to map them.
--
-- Money is always integer cents. The only double precision columns are genuine fractions
-- (ownership shares, categorization weights, transaction fractions, confidences).
--
-- Deletion rules are spelled out on every foreign key rather than left to the NO ACTION
-- default, because what should vanish with its parent and what should block the delete is a
-- judgement call in each case and not one to rediscover later.

CREATE TABLE users (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    name text NOT NULL UNIQUE,
    full_name text NOT NULL,
    password_hash text NOT NULL
);

CREATE TABLE categories (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    name text NOT NULL,
    description text NOT NULL,
    color text,
    parent_id uuid REFERENCES categories (id) ON DELETE SET NULL,

    -- desired maximum spending per month, in cents
    monthly_limit integer,

    CONSTRAINT categories_not_own_parent CHECK (parent_id IS DISTINCT FROM id),
    CONSTRAINT categories_monthly_limit_positive CHECK (monthly_limit IS NULL OR monthly_limit > 0)
);

CREATE INDEX categories_parent_id_idx ON categories (parent_id);

CREATE TABLE accounts (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    -- RESTRICT: deleting a user who still has accounts would orphan their whole history,
    -- so the accounts have to go first and deliberately
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE RESTRICT,

    name text NOT NULL,
    description text NOT NULL,
    color text,
    iban text,

    kind text NOT NULL,
    availability text NOT NULL,
    risk text NOT NULL,

    -- at its opening the account is implicitly assumed to have had a balance of zero
    opened timestamptz NOT NULL,
    closed timestamptz,

    ownership_fraction double precision NOT NULL,

    -- the mirror of this account in another user's books. The reverse link has to be kept in
    -- step by the application; a CHECK cannot see the other row.
    sync_account_id uuid REFERENCES accounts (id) ON DELETE RESTRICT,
    sync_invert boolean,

    CONSTRAINT accounts_kind_known CHECK (kind IN (
        'cash', 'debit', 'credit', 'debt', 'stocks', 'real_estate', 'virtual', 'other'
    )),
    CONSTRAINT accounts_availability_known CHECK (availability IN (
        'immediately', 'days', 'weeks', 'months', 'years', 'decades'
    )),
    CONSTRAINT accounts_risk_known CHECK (risk IN (
        'none', 'slight', 'low', 'medium', 'high', 'huge'
    )),
    CONSTRAINT accounts_closed_after_opened CHECK (closed IS NULL OR closed > opened),
    CONSTRAINT accounts_ownership_fraction_range
        CHECK (ownership_fraction > 0 AND ownership_fraction <= 1),
    CONSTRAINT accounts_not_synced_to_itself CHECK (sync_account_id IS DISTINCT FROM id),
    CONSTRAINT accounts_synchronization_complete
        CHECK ((sync_account_id IS NULL) = (sync_invert IS NULL))
);

CREATE INDEX accounts_user_id_idx ON accounts (user_id);
CREATE INDEX accounts_sync_account_id_idx ON accounts (sync_account_id);

-- Expenses are upstream data with no owner of their own: who they belong to follows from the
-- accounts their transactions touch. The per-user view of one is expenses_rendered.
CREATE TABLE expenses (
    id uuid PRIMARY KEY DEFAULT uuidv7(),

    title text NOT NULL,
    store text NOT NULL,
    description text NOT NULL,
    comments text NOT NULL,

    -- reference for fractional transactions, in cents; null when only fixed amounts are used
    reference_amount integer,

    -- the period the expense is consumed over, distinct from the dates its transactions
    -- settled on. Equal endpoints mean an ordinary expense; a span means a prepayment.
    booking_start timestamptz NOT NULL,
    booking_end timestamptz NOT NULL,

    -- only a stanza for a recurring expense, never counted in any analysis
    is_template boolean NOT NULL DEFAULT false,
    -- should be looked at again when preparing tax forms
    is_tax_relevant boolean NOT NULL DEFAULT false,
    -- needs a human to look at it first (missing info, low confidence, ...)
    is_unchecked boolean NOT NULL DEFAULT false,
    -- more transactions are expected before this can be completed
    is_incomplete boolean NOT NULL DEFAULT false,
    -- should not be considered for monthly spending
    is_extraordinary boolean NOT NULL DEFAULT false,

    -- neither is ever filtered or joined on, so they stay documents
    receipts jsonb NOT NULL DEFAULT '[]',
    positions jsonb NOT NULL DEFAULT '[]',

    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT expenses_booking_period_forward CHECK (booking_end >= booking_start),
    CONSTRAINT expenses_receipts_is_array CHECK (jsonb_typeof(receipts) = 'array'),
    CONSTRAINT expenses_positions_is_array CHECK (jsonb_typeof(positions) = 'array')
);

CREATE INDEX expenses_updated_at_idx ON expenses (updated_at DESC);
CREATE INDEX expenses_booking_period_idx ON expenses (booking_start, booking_end);

CREATE TABLE expense_transactions (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    expense_id uuid NOT NULL REFERENCES expenses (id) ON DELETE CASCADE,
    -- RESTRICT rather than CASCADE: dropping an account must not silently rewrite expenses
    -- that reference it, which would change historical totals
    account_id uuid NOT NULL REFERENCES accounts (id) ON DELETE RESTRICT,

    -- mongo stored these as an ordered array and the UI still shows them in that order
    idx integer NOT NULL,

    -- when the money actually moved
    date timestamptz NOT NULL,

    -- amounts are added to account balances, so a negative amount is a spend. Fractions are
    -- taken relative to the expense's reference_amount.
    amount integer,
    fraction double precision,

    comments text NOT NULL,
    statement text NOT NULL,

    CONSTRAINT expense_transactions_amount_xor_fraction
        CHECK (num_nonnulls(amount, fraction) = 1),
    CONSTRAINT expense_transactions_fraction_nonzero
        CHECK (fraction IS NULL OR fraction <> 0),
    -- Not DEFERRABLE: updating an expense deletes its transactions before reinserting them
    -- within one transaction, so immediate checking is fine, and a deferrable unique
    -- constraint cannot back an ON CONFLICT clause.
    CONSTRAINT expense_transactions_idx_unique UNIQUE (expense_id, idx)
);

CREATE INDEX expense_transactions_expense_id_idx ON expense_transactions (expense_id);
CREATE INDEX expense_transactions_account_date_idx ON expense_transactions (account_id, date);

CREATE TABLE expense_categorizations (
    expense_id uuid NOT NULL REFERENCES expenses (id) ON DELETE CASCADE,
    -- RESTRICT: deleting a category that expenses are filed under would silently
    -- recategorize them as uncategorized and move money between analysis buckets
    category_id uuid NOT NULL REFERENCES categories (id) ON DELETE RESTRICT,
    weight double precision NOT NULL,

    PRIMARY KEY (expense_id, category_id),
    CONSTRAINT expense_categorizations_weight_positive CHECK (weight > 0)
);

CREATE INDEX expense_categorizations_category_id_idx ON expense_categorizations (category_id);

CREATE TABLE balances (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    -- CASCADE, unlike expense_transactions: a balance is a statement about one account and
    -- means nothing once that account is gone, whereas a transaction belongs to an expense
    -- that would be left misreporting its total
    account_id uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,

    -- includes expenses dated strictly before this instant
    date timestamptz NOT NULL,
    amount integer NOT NULL,
    comments text NOT NULL,

    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX balances_account_date_idx ON balances (account_id, date);

CREATE TABLE expense_changes (
    id uuid PRIMARY KEY DEFAULT uuidv7(),

    -- deliberately not a foreign key: a change outlives the expense it describes
    target_id uuid NOT NULL,
    user_id uuid REFERENCES users (id) ON DELETE SET NULL,

    date timestamptz NOT NULL,

    -- the program that made the change (web app, CLI, ...)
    tool text,
    automatic boolean NOT NULL,
    -- how sure an automatic system was; meaningless for human changes
    confidence double precision NOT NULL,

    -- immutable snapshots of the whole expense before and after. Kept as documents on
    -- purpose: normalising them would let a later schema change rewrite history.
    old_state jsonb,
    new_state jsonb,

    CONSTRAINT expense_changes_has_a_state CHECK (num_nonnulls(old_state, new_state) >= 1),
    CONSTRAINT expense_changes_confidence_range CHECK (confidence >= 0 AND confidence <= 1),
    CONSTRAINT expense_changes_states_are_objects CHECK (
        (old_state IS NULL OR jsonb_typeof(old_state) = 'object')
        AND (new_state IS NULL OR jsonb_typeof(new_state) = 'object')
    )
);

CREATE INDEX expense_changes_target_id_idx ON expense_changes (target_id);
CREATE INDEX expense_changes_date_idx ON expense_changes (date DESC);

CREATE TABLE periodic_rules (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,

    title text NOT NULL,

    -- the expense this rule copies. Often but not always flagged is_template — moneydb let
    -- ordinary past expenses double as prototypes and the import preserves that.
    template_id uuid NOT NULL REFERENCES expenses (id) ON DELETE RESTRICT,

    period text NOT NULL,

    -- replace the template's title; %d, %m and %y are substituted per occurrence
    title_replacement text,
    -- replace the template's reference amount, in cents
    amount_replacement integer,

    -- occurrences at or before this instant have already been generated
    last_creation timestamptz NOT NULL,

    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT periodic_rules_period_known
        CHECK (period IN ('daily', 'weekly', 'monthly', 'yearly'))
);

CREATE INDEX periodic_rules_user_id_idx ON periodic_rules (user_id);

CREATE TABLE automation_rules (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,

    title text NOT NULL,
    template_id uuid NOT NULL REFERENCES expenses (id) ON DELETE RESTRICT,

    -- higher wins when several rules match the same delivery
    priority integer NOT NULL,

    -- matched against the delivery date formatted as dd.mm.yyyy HH:MM (UTC)
    regex_time text,
    -- matched against the statement text of the delivered transaction
    regex_statement text,
    filter_amount integer,
    -- CASCADE rather than SET NULL on purpose: a rule that loses its account filter would
    -- widen to match every delivery instead of none, so the rule goes with the account
    filter_account_id uuid REFERENCES accounts (id) ON DELETE CASCADE,

    last_delivery timestamptz,

    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX automation_rules_user_id_idx ON automation_rules (user_id);

-- Bank statement uploads overlap, so processed deliveries are remembered to keep a re-upload
-- from duplicating expenses. The unique constraint is what makes that safe under concurrent
-- uploads; a SELECT-then-INSERT is not.
CREATE TABLE seen_deliveries (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    account_id uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,

    date timestamptz NOT NULL,
    amount integer NOT NULL,
    statement text NOT NULL,

    -- the expense this delivery produced, absent when no rule matched
    expense_id uuid REFERENCES expenses (id) ON DELETE SET NULL,

    created_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT seen_deliveries_unique UNIQUE (user_id, account_id, date, amount, statement)
);

CREATE INDEX seen_deliveries_expense_id_idx ON seen_deliveries (expense_id);
